    "subtitle": "東京草地 2400m 經典大賽舞台",
    "form_desc": "東京芝2400mは、1コーナーの奥に設けられたポケットからのスタートです。スタート後の最初の直線は約350mとそれなりに長く、ここですぐにゆるやかな上り坂を迎えます。序盤にいきなり脚を使わされる構造ではないため、各馬が無理なく隊列を組みやすく、結果としてペースが落ち着きやすいコースになっています。 向正面は長い直線が続き、3コーナーから4コーナーにかけてはゆったりとした下り。ここで脚をためた馬たちが勢いをつけ、最後の直線525.9mに入っていきます。この直線の長さが「末脚勝負」のイメージを生むのですが、実態は少し違います。下りからの加速がそのまま生きるため、前で運んでいた馬がペースを引き上げてロングスパートに持ち込むと、後ろからは届きにくい。長い直線が必ずしも差し有利に直結しないのが、このコースの面白いところです。 つまり東京芝2400mは、「長い直線で末脚を問われる」一方で「スローのロングスパート戦になりやすく前残りも多い」という二面性を持ったコースです。実力が素直に反映される一方で、脚質面では見た目の印象と実データがずれる――この点を頭に入れておくと、データの読み方がぐっとクリアになります。",
