    "form_desc": "中山ダート1800mは、4コーナーの奥、スタンド前の直線からスタートします。スタート地点からほどなくして最初のコーナーが近づいてくるため、ゲートが開いた直後の先行争いが激しくなりやすいレイアウトです。さらにスタートして間もなく最初の上り坂を迎え、ここで一度ペースが緩急つきます。前に行きたい馬にとっては、ここで好位を取れるかどうかが勝負を大きく左右します。 その後は向正面を進み、3コーナーから4コーナーを回って最後の直線へ。直線は約310mと長くはなく、しかもゴール前にもう一度急坂が待ち構えています。コース全体を通して坂を2回越える構造で、スタミナとパワーの両方が問われるタフなコースです。直線が短いぶん、後ろから追い込んで差し切るには相当の脚力と展開の助けが必要になります。 つまり中山ダート1800mは、「スタート後すぐコーナーで先行争いが激化し、短い直線と急坂で前の利を守りやすい」という、典型的な前残りコースです。坂が2回あるタフさゆえに、底力のあるダート血統が安定して走る一方、位置取りの差がそのまま着順に直結しやすい――この点を頭に入れておくと、データの読み方がクリアになります。",
