    "form_desc": "東京芝1600mは、向正面の2コーナー寄りに設けられた引き込み線、いわゆるポケットからスタートします。ゲートが開くとすぐに長い向正面の直線へ合流し、最初に迎える3コーナーまで約540mと距離があります。この序盤の長さがこのコースの大きな特徴で、スタート直後に無理な先行争いになりにくく、隊列が比較的落ち着いて決まります。前に行きたい馬も慌てずポジションを取りにいけるため、テンの激しい消耗戦になりにくいレイアウトです。 その後は3コーナーから4コーナーを大きく回って最後の直線へ。直線は525.9m（Aコース）と国内でも最長級で、3コーナー手前のゆるやかな上り坂から3〜4コーナーの下りを経て、ゴール前にも坂が控えています。長い直線があるぶん、前にいる馬がそのまま押し切れるとは限らず、後方で脚をためた馬が末脚を伸ばして差し込む余地も十分に残されています。この「長い助走と長い直線」の組み合わせが、紛れの少なさと差しの利く適度なフラットさを生んでいます。 つまり東京芝1600mは、「序盤が長く隊列が落ち着き、長い直線で実力どおりに伸びてくる」という、マイルらしいバランス型のコースです。前残り一辺倒でも後方一気でもなく、勝負所で動ける位置にいて長い直線で確かな末脚を使える馬が安定して結果を出す――この点を頭に入れておくと、データの読み方がクリアになります。",
