    "subtitle": "阪神草地 2200m 內圈外回高難度中長途",
    "form_desc": "阪神芝2200mは、外回りコースの4コーナー出口付近からスタートします。ゲートが開くとまず下り坂を進み、最初のコーナーまで約525mと長い助走区間があります。この序盤の長さのおかげで、スタート直後にいきなり激しい先行争いになりにくく、隊列が比較的落ち着いて決まりやすいレイアウトです。ただし1コーナーへ向かう途中で早くも急坂を一度上ることになり、ここがスタミナを要求する最初のポイントになります。 3〜4コーナーは内回りコースを使い、最後の直線は約356m（Aコース）と中央4場のなかでは短い部類です。短い直線にもかかわらず侮れないのが、 ゴール前に控える高低差約1.8mの急坂 です。このコースはスタート後と最後の直線で計2回坂を上る構造で、底力に欠ける馬は最後の坂で甘くなります。直線が短いぶん、坂下までに前で運べているかどうかが大きく、前にいる馬が止まりにくい一方、坂で確実に伸びるパワーも問われます。 つまり阪神芝2200mは、「序盤の隊列は落ち着くが、2回の坂越えと最後の急坂でごまかしが利かない」総合力勝負のコースです。グランプリ・宝塚記念がこの舞台で行われるのも納得で、底力に欠ける馬は坂で脱落していきます。スピードだけでなく、持続力とパワーを兼ね備えた馬が安定して結果を出す――この点を頭に入れておくと、データの読み方がはっきりします。",
    "sum_desc": "1番人気は複勝率63.8％、3番人気以内で複勝率41％超。上位人気は堅実だが、他コースよりやや割れるため過信は禁物 6番人気以下は複勝率17.3％以下に低下。ただし宝塚記念のメイショウタバル（7番人気）のように人気薄の激走も一定あり、4-5番人気（26.0％）までは相手に押さえたい 脚質は逃げ・先頭34.2％、先行27.0％、中団25.5％と前〜中団が優勢。後方一気（7.6％）は急坂で苦戦するため割り引く 馬番は内寄り（1-4番26.2％）がわずかに有利だが差は小さい。枠番別・種牡馬別はサンプルが少なく参考程度に 種牡馬はドゥラメンテ・ゴールドシップ・ハービンジャーなどスタミナ・底力型が上位。キレ型のディープインパクトは勝ち切れず（勝率2.2％）、パワー・持続型が向く 馬齢は4歳（複勝率29.5％）がピーク、6歳以上（10.5％）は急落。馬場は良で最も走り、渋るほど紛れが増える",
