    "form_desc": "中山芝2000mは、4コーナーを回り切った正面スタンド前の入り口付近からスタートします。ゲートが開くと1コーナーへ向かい、内回りをぐるりと1周する形です。最初のコーナーまでは約405mと短めで、しかもスタート直後にも上り坂が待っています。序盤から坂を上りながらポジションを取りにいくため、テンの先行争いが慌ただしくなりやすく、前に行きたい馬は早めに動かざるを得ません。この「短い助走＋スタート直後の坂」という序盤の構造が、コースの性格を大きく決めています。 コーナーを4つ回って向かう最後の直線は、わずか310mしかありません。国内の芝コースとしては短い部類で、しかもそのゴール前には高低差約2.2mの急坂が控えています。コース全体では序盤とゴール前で坂を2回上ることになり、見た目以上にタフな構造です。直線が短いため後方の馬が一気に差し切るには時間が足りず、坂を上りきる底力と、それまでに前で脚をためられるポジション取りの両方が問われます。 つまり中山芝2000mは、「短い助走で先行争いが起き、短い直線と急坂で前の利が守られる」という、中山らしい前残り傾向の強いコースです。後ろから差し届かせるのは簡単ではなく、前で運べる脚質と、急坂を2回上りきるパワーを備えた馬が安定して結果を出す――この点を頭に入れておくと、データの読み方がクリアになります。",
