    "form_desc": "東京ダート1600mは、向正面の芝コース上にゲートが置かれ、各馬はおよそ150m芝を走ってからダートに合流します。芝はダートよりスピードが出るため、ここでスムーズに加速できた馬が前のポジションを取りやすくなります。そして重要なのが、 外の枠に入るほど芝を走る距離が長くなる という点です。外枠の馬は加速しながらダートへ入っていけるうえ、内の馬が巻き上げる砂（キックバック）も浴びにくい。この二つの理由から、東京ダート1600mは数あるダートコースのなかでも珍しく、外枠が明確に有利なコースになっています。砂をかぶると走る気をなくす馬も多いダートでは、この差は小さくありません。 ダートに入ってからは、向正面から3コーナー、4コーナーと外を回り、最後の直線へと向かいます。この直線が約501.6mと長く、国内のダートコースでは最長クラスです。直線の入り口には高低差約2.4mの急坂があり、残り300m付近からこの坂を上っていきます。坂を上りきるパワーが要る一方、直線が長いぶん脚をためた馬がしっかり伸びる余地もあり、ゴール前ではしばしば差し・追い込みが届く決着になります。短い直線で前残りが決まりやすい中山ダート1800mとは対照的な性格と言えます。 つまり東京ダート1600mは、「芝スタートで外枠と先行勢が立ち回りやすく、長い直線と急坂で差しも届く」という、ダートのなかでは比較的バランスのとれたコースです。前で運べる脚質が基本的に有利なのは変わりませんが、長い直線が後方の馬にも逆転の余地を残します。この「前有利、ただし差しも届く」という二面性を頭に入れておくと、データの読み方がクリアになります。",
