    "form_desc": "阪神芝1600mは外回りコースを使用します。スタートは向正面の2コーナー奥付近で、ゲートが開くとまず400mほどの直線を進み、緩やかに3コーナーへと入っていきます。スタート後にしばらく直線が続くため、枠順による位置取りの不利が出にくい構造で、各馬がじっくりとポジションを定められます。バックストレッチが長く、3コーナー・4コーナーのカーブもゆったりしているのが外回りの特徴で、道中は無理なく脚をためられます。 そして最大の特徴が、4コーナーを回って向かう約473.6mの直線です。これは右回りコースとしては国内最長で、しかも残り600m付近から直線の半ばにかけてはいったん緩やかな下り坂が続き、そのスピードに乗ったままゴール前の急坂へと突入します。急坂は高低差約1.8mながら勾配は1.5％となかなかきつく、下りで加速した勢いを坂の上まで持続できるかが勝負の分かれ目です。 長く脚を使える持続力と、坂を上りきるパワーの両方 が問われるレイアウトと言えます。 つまり阪神芝1600m（外回り）は、「道中で脚をためやすく、長い直線と急坂で持続力とパワーが試される」コースです。マイル戦としてはペースが上がりにくくスローになりやすいため、前にいる馬が止まりにくい一方、下り坂を利して動ける器用さと末脚を兼ね備えた馬が浮上します。逃げ切りに固執するより、好位で脚をためて直線で抜け出す競馬がはまりやすい――この点を頭に入れておくと、データの読み方がクリアになります。",
