    "subtitle": "中山泥地 1200m 草地斜向發走極速短途",
    "form_desc": "中山ダート1200mは、2コーナー奥のポケットに置かれた芝の上からスタートします。各馬はまず芝を走り、その後ダートへと入っていきます。芝はダートよりもスピードが出るため、ここでスタートダッシュが決まりやすく、序盤の先行争いが激しくなりやすいのが特徴です。3コーナーまでは約502mとたっぷり距離があり、しかもこの区間はやや下り坂。勢いがつきやすく、 他場の1200m戦と比べても明らかにハイペースになりやすい コースとして知られています。 そして最大の特徴が、4コーナーを回ってからゴールまでの直線です。直線は308mと短く、しかもそこには中山名物の急坂が待ち構えています。高低差は約2mで、とくに 最後の200mは最大勾配2.24％という日本一のきつさ を誇ります。ハイペースで飛ばしてきた各馬にとって、この急坂は脚を一気に奪う最後の関門です。序盤の下り坂で加速し、終盤の急坂で減速する――「急→緩→急」のリズムが、このコースの厳しさを生んでいます。 つまり中山ダート1200mは、「芝スタートで序盤からスピードが出やすく、短い直線と日本屈指の急坂で前の利が守られる」コースです。ハイペースになりやすいぶん差しが決まりそうにも思えますが、実際には直線が短く急坂もあるため、後方から差し切るには時間も脚も足りません。前で粘れるスピードと、急坂を踏ん張るパワーを兼ね備えた馬が安定して結果を出す――この点を頭に入れておくと、データの読み方がクリアになります。",
    "sum_desc": "1番人気は複勝率67.0％、3番人気以内で複勝率42％超。実力反映度の高いコースで、上位人気を軸に据える組み立てが基本 6番人気以下は複勝率15.7％以下に落ち込む。穴を狙うなら4-5番人気（複勝率26.5％）までが現実的な上限 脚質は逃げ・先頭が複勝率51.7％と図抜けて高く、後方（4.0％）は壊滅的。軸はまず逃げ・先行できる馬から探す 枠順は外枠がやや有利（6〜8枠で複勝率21％超）。芝スタートで前を取りやすく、内の1〜3枠（17〜18％）は割引 種牡馬はヘニーヒューズ・ダノンレジェンド・アジアエクスプレスなど米国型のダート短距離血統が上位。芝寄りの血統は割引 馬齢は2〜4歳が横並びで好走、6歳以上（11.4％）は急落。牡馬が明確に有利で、馬場状態はほぼ気にしなくてよい",
