    "form_desc": "東京芝1800mは、1・2コーナー付近のポケットからスタートします。2コーナーまでは約150mと短いのですが、その先のポケットを斜めに横切って向正面へ入り、3コーナーまでは約750mもの長い直線が続きます。最初のコーナーまでにたっぷり距離があるため、序盤の先行争いはさほど激しくなりません。各馬が無理なく隊列を決められるぶん、極端なハイペースになりにくく、力のある馬が能力を出し切りやすいのがこのコースの特徴です。 そして最大の特徴が、4コーナーを回って向かう約525.9mの直線です。国内屈指の長さを誇り、しかも直線の途中には高低差約2mの急坂が待ち受けます。コース全体の高低差は約2.7mで、長い直線と坂が、生半可な脚では通用しない構造を作っています。先行して粘り込むにも、後方から差し込むにも、最後まで脚を持続させる力が欠かせません。 瞬発力と底力、そのどちらか一方では足りない のがこのコースの厳しさです。 つまり東京芝1800mは、「序盤は落ち着きやすく、長い直線と急坂で総合力が試される」コースです。先行有利の傾向はあるものの、長い直線があるため前にいるだけでは押し切れず、速い上がりを使えなければ直線で差されてしまいます。逆に後方からでも、確かな末脚があれば届く余地が残されています。紛れが少なく、能力がそのまま着順に出やすい――この点を頭に入れておくと、データの読み方がクリアになります。",
