    "subtitle": "東京草地 1400m 緩上坡助跑穩健短途",
    "form_desc": "東京芝1400mは、向正面の中ほどからスタートします。最初のコーナー（3コーナー）までは約340mと距離があり、しかもその途中には約60mの緩やかな上り坂が待っています。このため序盤からペースが上がりにくく、 他場の1400m戦に比べて落ち着いた流れになりやすい のが特徴です。コーナーは3コーナー・4コーナーの2つだけというワンターン構造で、向正面で隊列が決まると、そのまま最後の直線勝負へと向かいます。 そして最大の特徴が、約525.9mの長い直線です。国内屈指の長さで、その途中にはゴール前の坂もあります。1400mという短い距離ながら、この長い直線が「前に行ったもの勝ち」を許さず、後方からでも確かな末脚があれば届く余地を残しています。スローペースで隊列が落ち着き、最後の直線でヨーイドンの上がり勝負になる――これが東京芝1400mの典型的な決まり方です。短距離の追走スピードだけでなく、長く脚を使える瞬発力が問われます。 つまり東京芝1400mは、「長い助走でペースが落ち着き、長い直線で末脚が問われる」コースです。前で運べる脚質がやや有利なのは確かですが、前残りが極端なコースではなく、中団からの差しも十分に決まります。位置取りに神経質になるより、確かな末脚を持っているかどうかを重視したい――この点を頭に入れておくと、データの読み方がクリアになります。",
    "sum_desc": "1番人気は複勝率66.9％、3番人気以内で複勝率39％超。標準的に信頼でき、上位人気を軸に据える組み立てが基本 6番人気以下は複勝率15.7％以下に落ち込む。穴を狙うなら4-5番人気（複勝率28.1％）までが現実的な上限 脚質は逃げ・先頭31.9％、先行29.4％と前がやや有利だが差は小さく、中団（20.5％）の差しも届く。軸は先行〜中団で速い上がりを使える馬から 枠順は外枠有利・内枠不利（8枠22.8％、1枠16.8％）。馬番も5〜13番の中〜外が優秀で、最内1-4番と最外17番以降は割引 種牡馬はディープインパクト・イスラボニータ・ロードカナロアなど切れ味とスピードを伝える血統が上位 馬齢は3〜4歳（複勝率23％前後）がピーク、2歳も好走。5歳以上は急落。牡馬がやや有利で、馬場状態はほぼ気にしなくてよい",
