    "form_desc": "東京ダート1400mは、向正面の入り口付近からスタートします。最初のコーナー（3コーナー）までは約440mと距離があり、各馬はポジションを取る時間に余裕があります。このため、ほかの多くのダート短距離コースのように「枠順で位置取りが決まってしまう」ことが少なく、外枠の馬でも無理なく好位を狙えるのが特徴です。序盤はスピードに乗りやすくハイペースになりがちですが、最初のコーナーまで距離があるぶん、極端な先行争いの不利は生じにくくなっています。 そして最大の特徴が、501.6mという日本一長いダートの直線です。しかも平坦ではなく、残り400m地点から高低差2.4mの急坂が待ち受けます。コース全体の高低差は2.5m。長い直線で脚を使ったうえに急坂を上らされるため、スピードだけでなく、長く脚を持続させるスタミナとパワーが欠かせません。ハイペースで飛ばした逃げ・先行馬が最後の坂で苦しくなる一方、後方で脚をためた差し馬が長い直線で台頭する――そんな決着も少なくありません。 つまり東京ダート1400mは、「序盤はハイペースになりやすく、日本一長い直線と急坂で持続力が問われる」コースです。前で運べる脚質が基本的に有利ではあるものの、長い直線と急坂が前の利を削ぐため、差しも十分に届きます。枠の有利不利が小さいぶん、最後は純粋に能力と適性が問われる――この点を頭に入れておくと、データの読み方がクリアになります。",
