    "form_desc": "中京ダート1800mは、ホームストレッチ（ゴール前の直線）の上り坂の途中からスタートします。1周目のゴール板前を過ぎて1コーナーへ向かい、1〜2コーナーはほぼ平坦。向正面に入るとしばらく緩い上り坂が続き、残り980m付近から今度は緩やかな下り坂に転じます。3コーナー・4コーナーは半径が徐々にきつくなるスパイラルカーブで、ここを下りながら加速していくのがこのコースの特徴です。下り坂で勢いがつくため、コーナーで一気にペースが上がりやすくなります。 そして最後の直線は約410.7mと、ダートコースとしては長い部類です。ただし平坦ではなく、ゴール手前380m地点から220m地点にかけて、高低差1.8m・勾配1.14％の急坂が待ち受けます。ラスト220mはほぼ平坦になりますが、コース全体の高低差は3.4mと大きく、 中山や阪神に匹敵する底力が問われる 構造です。下りで加速したスピードを坂の上まで持続できるか、そしてスタミナが最後まで保つか――1800mという距離も相まって、総合力の高い馬でなければ好走できません。 つまり中京ダート1800mは、「下り坂で加速し、長い直線と急坂で底力とスタミナが試される」コースです。平均から速めのペースを追走しつつ、最後の急坂でしっかりした脚を使える馬が浮上します。後方一辺倒では届きにくく、好位から抜け出す競馬が正攻法。2000m前後の距離をこなせるスタミナがあると、なお心強いコースです。この点を頭に入れておくと、データの読み方がクリアになります。",
    "sum_desc": "1番人気は複勝率68.9％、3番人気以内で複勝率44％超。実力反映度の高いコースで、上位人気を軸に据える組み立てが基本 6番人気以下は複勝率15.4％以下に落ち込む。穴を狙うなら4-5番人気（複勝率29.7％）までが現実的な上限 脚質は逃げ・先頭が複勝率48.4％・勝率21.2％と図抜けて高い前残り。後方（5.0％）は苦しい。軸は逃げ・先行できる馬から 枠順の差はほぼなく、馬番も13番より外がやや割引になる程度。枠より「前に行ける脚質か」を優先して判断 種牡馬はドゥラメンテ・キタサンブラック・キングカメハメハなど底力を伝える中距離パワー血統が上位 馬齢は2〜4歳が複勝率24〜26％で好走、5歳以上は急落。牡馬が明確に有利で、馬場状態はまったく気にしなくてよい",
