    "form_desc": "京都芝2200mは外回りコースを使用します。スタートは内回りの4コーナーが終わった先、正面スタンド前付近です。最初のコーナーまでは約400mと長く、序盤でじっくりとポジションを定められるため、極端な先行争いにはなりにくいレイアウトです。1コーナー・2コーナーを回って向正面に入ると、京都名物の「淀の坂」が待っています。高低差は約4.3mあり、向正面から坂を上り、3コーナーの途中からは下りに転じます。 多くの馬がこの下り坂を利して一気にペースを上げる のが、京都の中長距離戦に共通する特徴です。 3コーナー・4コーナーはゆったりとした大きな造りで、スピードを落とさずに回れます。そして最後の直線は約400mとやや長め。ここで重要なのが、 阪神や中山のような急坂がなく、ゴールまで平坦だ という点です。下り坂で得た勢いをそのまま生かせるため、芝が軽いときは高速決着になりやすく、スピードと瞬発力が大きな武器になります。一方で2200mという距離と3コーナーの坂のぶん、最後まで脚を保たせるスタミナも欠かせません。 つまり京都芝2200m（外回り）は、「下り坂で加速し、平坦な直線でスピードを持続させつつ、距離と坂をこなすスタミナも問われる」コースです。ゴール前に坂がないぶん前に行った馬の脚が止まりにくく、先行勢が粘り込みやすい構造になっています。同じ2200mのG1コースでも、内回りを使い直線も短く、ゴール前の急坂で底力が問われる阪神芝2200m（宝塚記念の舞台）とは対照的な性格と言えます。スピードとスタミナのバランス――この点を頭に入れておくと、データの読み方がクリアになります。",
    "sum_desc": "1番人気は複勝率67.9％、2番人気も57.1％と上位2頭が堅実。まずは上位人気から軸を選ぶ。10番人気以下（1.7％）はほぼ来ない 穴を狙うなら4-5番人気（複勝率32.1％）までが現実的な上限。人気薄の一発は期待しにくい 脚質は前〜好位有利（逃げ・先頭34.6％、先行37.5％）。後方（3.4％）は壊滅的で、軸は前で運べる馬から 枠順は内枠がやや有利（内1〜3枠29.5％、馬番1-4番29.9％）。外寄りより内目の先行馬を上位に 種牡馬はキズナ・ジャスタウェイ・オルフェーヴルなどスタミナ・底力型が上位（サンプル少なく参考値） 馬齢は3〜5歳が複勝率26〜27％で好走、6歳以上（15.2％）は急落。牡馬がやや有利で、馬場状態はほぼ気にしなくてよい",
