    "form_desc": "東京芝2000mは、1・2コーナーの端に設けられた専用のポケットからスタートします。このポケットは芝2000mだけで使われる特殊な発走地点で、スタートから最初のコーナーまではわずか約130mと非常に短く、そのコーナーも鋭角です。最初のコーナーまでに距離がないため、各馬は一気にポジション争いをすることになり、 外枠の馬は内の馬に被されたり、外を回らされたりする不利を受けやすい のが、このコース最大の注意点です。とはいえ中距離戦らしく、騎手はハイペースになりすぎないよう折り合いをつけてレースを進めます。 コーナーを回って向正面に入ると、あとは3コーナー・4コーナーを経て最後の直線へ。直線は約525.9mと国内屈指の長さで、その途中にはゴール前の坂があります。コース全体の高低差は約2.7m。長い直線と坂が、小手先の脚では通用しない構造を作っています。1周は2083.3mという広大なスケールで、まさに「日本一の実力コース」。先行して粘るにも、後方から差すにも、最後まで確かな脚を使えなければ上位に食い込めません。 つまり東京芝2000mは、「特殊なポケットから短い助走でコーナーを迎え、長い直線と坂で地力が試される」コースです。序盤の立ち回りで枠の有利不利が出やすい一方、最後は長い直線での総合力勝負。先行有利の傾向はあるものの、前にいるだけでは押し切れず、速い上がりを使えなければ差されてしまいます。能力がそのまま着順に出やすい――この点を頭に入れておくと、データの読み方がクリアになります。",
